73	    fn build_order_relevance(
74	        &mut self,
75	        order_by: &OrderByRelevance,
76	        needs_reversed_order: bool,
77	        ctx: &Context<'_>,
78	    ) -> OrderByDefinition {
79	        let columns: Vec<Expression> = order_by
80	            .fields
81	            .iter()
82	            .map(|sf| sf.as_column(ctx).opt_table(self.parent_alias.clone()).into())
83	            .collect();
84	        let order_column: Expression = text_search_relevance(&columns, order_by.search.clone()).into();
85	        let order: Option<Order> = Some(into_order(&order_by.sort_order, None, needs_reversed_order));
86	        let order_definition: OrderDefinition = (order_column.clone(), order);
87	
88	        OrderByDefinition {
89	            order_column,
90	            order_definition,
91	            joins: vec![],
92	        }
93	    }
