    /// Returns all hops of the path except the final one on which the aggregation is performed.
    /// These are the intermediary relations that need to be traversed (joined) before reaching
    /// the relation that gets aggregated.
    pub fn intermediary_hops(&self) -> &[OrderByHop] {
        // The path of a to-many aggregation always has at least one hop (the aggregation hop),
        // so splitting off the last element is always safe.
        &self.path[..self.path.len() - 1]
    }

