/// The last join of the returned list always targets the related model, so its alias can be used
/// as the "previous join" of the next hop.
pub(crate) fn compute_join(
    field: &RelationFieldRef,
    alias: &str,
    parent_alias: Option<&str>,
    ctx: &Context<'_>,
) -> Vec<AliasedJoin> {
    if field.relation().is_many_to_many() {
        compute_m2m_join(field, alias, parent_alias, ctx)
    } else {
        vec![compute_one2m_join(field, alias, parent_alias, ctx)]
    }
}

/// Computes the two joins required to traverse a many-to-many relation from a parent model to the
/// related model, going through the implicit join table.
///
/// Preview of the rendered SQL:
/// ```sql
/// LEFT JOIN _ParentToChild AS <alias>_m2m
///   ON (<Parent | previous_join>.id = <alias>_m2m.<ParentId>)
/// LEFT JOIN Child AS <alias>_Child
///   ON (<alias>_m2m.<ChildId> = <alias>_Child.id)
/// ```
fn compute_m2m_join(
    field: &RelationFieldRef,
    alias: &str,
    parent_alias: Option<&str>,
    ctx: &Context<'_>,
) -> Vec<AliasedJoin> {
    let m2m_table_alias = format!("{}_m2m", alias);
    let child_table_alias = format!("{}_{}", alias, field.related_model().name());

    // --- Join from the parent model to the join table ---
    // Columns on the join table pointing to the parent model (e.g. _ParentToChild.A).
    let link_parent_columns = field.related_field().m2m_columns(ctx);
    // Primary identifier of the parent model (e.g. Parent.id).
    let parent_ids: ModelProjection = field.model().primary_identifier().into();

    let link_conditions: Vec<Expression> = parent_ids
        .as_columns(ctx)
        .zip(link_parent_columns)
        .map(|(parent_col, link_col)| {
            let parent_col = match parent_alias {
                Some(prev) => Column::from((prev.to_owned(), parent_col.name.to_string())),
                None => parent_col,
            };
            let link_col = Column::from((m2m_table_alias.clone(), link_col.name.to_string()));

            parent_col.equals(link_col).into()
        })
        .collect();

    let link_join = field
        .as_table(ctx)
        .alias(m2m_table_alias.clone())
        .on(ConditionTree::And(link_conditions));

    // --- Join from the join table to the related model ---
    // Columns on the join table pointing to the related model (e.g. _ParentToChild.B).
    let link_child_columns = field.m2m_columns(ctx);
    // Primary identifier of the related model (e.g. Child.id).
    let child_ids: ModelProjection = field.related_model().primary_identifier().into();

    let child_conditions: Vec<Expression> = link_child_columns
        .into_iter()
        .zip(child_ids.as_columns(ctx))
        .map(|(link_col, child_col)| {
            let link_col = Column::from((m2m_table_alias.clone(), link_col.name.to_string()));
            let child_col = Column::from((child_table_alias.clone(), child_col.name.to_string()));

            link_col.equals(child_col).into()
        })
        .collect();

    let child_join = field
        .related_model()
        .as_table(ctx)
        .alias(child_table_alias.clone())
        .on(ConditionTree::And(child_conditions));

    vec![
        AliasedJoin {
            alias: m2m_table_alias,
            data: Join::Left(link_join),
        },
        AliasedJoin {
            alias: child_table_alias,
            data: Join::Left(child_join),
        },
    ]
}

