157	        // these hops can be a one-to-many or a many-to-many relation, hence the use of `compute_join`.
158	        for hop in order_by.intermediary_hops() {
159	            let hop_joins = compute_join(
160	                hop.as_relation_hop().unwrap(),
161	                &self.join_prefix(),
162	                previous_alias.as_deref(),
163	                ctx,
164	            );
