175	        // We perform the aggregation on the last hop of the path.
176	        let last_aggr_join = compute_aggr_join(
177	            order_by.aggregation_hop().as_relation_hop().unwrap(),
178	            aggregation_type,
179	            None,
180	            ORDER_AGGREGATOR_ALIAS,
181	            &self.join_prefix(),
182	            previous_alias.as_deref(),
183	            ctx,
184	        );
185	
186	        // This is the final column identifier to be used for the scalar field to order by.
187	        // `{last_join_alias}.{ORDER_AGGREGATOR_ALIAS}`
188	        let order_by_column = Column::from((last_aggr_join.alias.to_owned(), ORDER_AGGREGATOR_ALIAS.to_owned()));
